selector_to_html = {"a[href=\"#buffer-registration\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Buffer Registration<a class=\"headerlink\" href=\"#buffer-registration\" title=\"Link to this heading\">#</a></h4><p><strong>Alternative registration via window:</strong></p>", "a[href=\"#p2p-engine\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">P2P Engine<a class=\"headerlink\" href=\"#p2p-engine\" title=\"Link to this heading\">#</a></h3><p>The FlagCX P2P Engine provides a point-to-point engine interface for one-sided RDMA operations, designed for integration with transfer frameworks such as NIXL.</p>", "a[href=\"#removed-apis\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Removed APIs<a class=\"headerlink\" href=\"#removed-apis\" title=\"Link to this heading\">#</a></h4><p>The following API has been removed from the public interface:</p>", "a[href=\"#unirunner-mode\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">UniRunner mode<a class=\"headerlink\" href=\"#unirunner-mode\" title=\"Link to this heading\">#</a></h3><p>FlagCX provides a unified heterogeneous communication mode called <strong>uniRunner</strong>, which implements 11 chip-decoupled collective communication algorithms. To enable uniRunner mode, set the following environment variable before launching your application:</p>", "a[href=\"#installation-and-compilation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation and compilation<a class=\"headerlink\" href=\"#installation-and-compilation\" title=\"Link to this heading\">#</a></h2><p>Refer to <a class=\"reference internal\" href=\"getting-started.html\"><span class=\"std std-doc\">Getting Started</span></a> for FlagCX compilation and installation.</p>", "a[href=\"#key-features\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#environment-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment configuration<a class=\"headerlink\" href=\"#environment-configuration\" title=\"Link to this heading\">#</a></h2><p>Refer to the environment setup section in the <a class=\"reference internal\" href=\"getting-started.html\"><span class=\"std std-doc\">Getting Started</span></a> page.</p>", "a[href=\"#one-sided-rdma-operations\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">One-sided RDMA operations<a class=\"headerlink\" href=\"#one-sided-rdma-operations\" title=\"Link to this heading\">#</a></h3><p>FlagCX supports one-sided RDMA operations for heterogeneous communicators backed by RDMA-capable network adaptors. These operations require prior buffer registration.</p>", "a[href=\"#engine-lifecycle\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Engine Lifecycle<a class=\"headerlink\" href=\"#engine-lifecycle\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#homogeneous-training-with-flagcx-flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Homogeneous training with FlagCX + FlagScale<a class=\"headerlink\" href=\"#homogeneous-training-with-flagcx-flagscale\" title=\"Link to this heading\">#</a></h2><p>The following steps shows an example in which we run the LLaMA3-8B model on Nvidia A800 GPUs.</p>", "a[href=\"#api-reference\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">API Reference<a class=\"headerlink\" href=\"#api-reference\" title=\"Link to this heading\">#</a></h2><h3>Device Handle Management<a class=\"headerlink\" href=\"#device-handle-management\" title=\"Link to this heading\">#</a></h3><p>FlagCX introduces a device handle API that separates device/CCL adaptor lifecycle from communicator management. The previous <code class=\"docutils literal notranslate\"><span class=\"pre\">flagcxHandlerGroup</span></code> approach is now deprecated.</p>", "a[href=\"#one-sided-api\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">One-Sided API<a class=\"headerlink\" href=\"#one-sided-api\" title=\"Link to this heading\">#</a></h4><p><strong>Example - Async RDMA with completion counter:</strong></p>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Communication API test<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#deprecated-apis\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Deprecated APIs<a class=\"headerlink\" href=\"#deprecated-apis\" title=\"Link to this heading\">#</a></h4><p>The following APIs are deprecated and will be removed in a future release:</p>", "a[href=\"#heterogeneous-tests-using-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Heterogeneous tests using FlagCX<a class=\"headerlink\" href=\"#heterogeneous-tests-using-flagcx\" title=\"Link to this heading\">#</a></h2><h3>UniRunner mode<a class=\"headerlink\" href=\"#unirunner-mode\" title=\"Link to this heading\">#</a></h3><p>FlagCX provides a unified heterogeneous communication mode called <strong>uniRunner</strong>, which implements 11 chip-decoupled collective communication algorithms. To enable uniRunner mode, set the following environment variable before launching your application:</p>", "a[href=\"#nccl-wrapper-plugin\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NCCL wrapper plugin<a class=\"headerlink\" href=\"#nccl-wrapper-plugin\" title=\"Link to this heading\">#</a></h3><p>For NVIDIA platforms, FlagCX provides an NCCL wrapper plugin that builds a drop-in <code class=\"docutils literal notranslate\"><span class=\"pre\">libnccl.so</span></code>. This allows any NCCL-based application (PyTorch, DeepSpeed, Megatron-LM) to transparently use FlagCX without code changes:</p>", "a[href=\"#memory-registration\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Memory Registration<a class=\"headerlink\" href=\"#memory-registration\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#connection-management\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Connection Management<a class=\"headerlink\" href=\"#connection-management\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#new-apis-recommended\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">New APIs (Recommended)<a class=\"headerlink\" href=\"#new-apis-recommended\" title=\"Link to this heading\">#</a></h4><p><strong>Usage pattern:</strong></p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><h2>Environment configuration<a class=\"headerlink\" href=\"#environment-configuration\" title=\"Link to this heading\">#</a></h2><p>Refer to the environment setup section in the <a class=\"reference internal\" href=\"getting-started.html\"><span class=\"std std-doc\">Getting Started</span></a> page.</p>", "a[href=\"#communication-api-test\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Communication API test<a class=\"headerlink\" href=\"#communication-api-test\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#one-sided-operations\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">One-Sided Operations<a class=\"headerlink\" href=\"#one-sided-operations\" title=\"Link to this heading\">#</a></h4><p>See <a class=\"reference internal\" href=\"environment-variables.html\"><span class=\"std std-doc\">environment-variables.md</span></a> for P2P Engine configuration variables (<code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGCX_P2P_*</span></code>).</p>", "a[href=\"#torch-api-test\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Torch API test<a class=\"headerlink\" href=\"#torch-api-test\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#device-handle-management\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Device Handle Management<a class=\"headerlink\" href=\"#device-handle-management\" title=\"Link to this heading\">#</a></h3><p>FlagCX introduces a device handle API that separates device/CCL adaptor lifecycle from communicator management. The previous <code class=\"docutils literal notranslate\"><span class=\"pre\">flagcxHandlerGroup</span></code> approach is now deprecated.</p>", "a[href=\"#changed-apis\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Changed APIs<a class=\"headerlink\" href=\"#changed-apis\" title=\"Link to this heading\">#</a></h4><p>Note: The caller must provide a valid pointer to a flagcxUniqueId struct.</p>", "a[href=\"environment-variables.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagCX Environment Variables<a class=\"headerlink\" href=\"#flagcx-environment-variables\" title=\"Link to this heading\">#</a></h1><p>This document provides a comprehensive reference for all environment variables used in FlagCX.</p>", "a[href=\"getting-started.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><h2>Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><p><strong>Reference Command for Container Creation:</strong></p><p>Modify the <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;Docker</span> <span class=\"pre\">name&gt;</span> <span class=\"pre\">&lt;mount</span> <span class=\"pre\">directory&gt;</span> <span class=\"pre\">&lt;mount</span> <span class=\"pre\">point&gt;</span></code> and choose the <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;Docker</span> <span class=\"pre\">Image&gt;</span></code> as needed.</p>", "a[href=\"#homogeneous-tests-using-flagcx\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Homogeneous tests using FlagCX<a class=\"headerlink\" href=\"#homogeneous-tests-using-flagcx\" title=\"Link to this heading\">#</a></h2><h3>Communication API test<a class=\"headerlink\" href=\"#communication-api-test\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
